#include <stdio.h>
#include <openssl/evp.h>
#include <openssl/sha.h>

int sha256_file(FILE *fp, unsigned char out[SHA256_DIGEST_LENGTH]) {
  unsigned char buf[4096];
  size_t n;
  int ret = -1;
  EVP_MD_CTX *ctx = EVP_MD_CTX_new();
  if (ctx == NULL) return -1;
  if (EVP_DigestInit_ex(ctx, EVP_sha256(), NULL) != 0) goto done;
  while ((n = fread(buf, 1, sizeof buf, fp)) > 0) {
    if (EVP_DigestUpdate(ctx, buf, n) != 0) goto done;
  }
  if (ferror(fp)) goto done;
  if (EVP_DigestFinal_ex(ctx, out, NULL) != 0) goto done;
  ret = 0;
done:
  EVP_MD_CTX_free(ctx);
  return ret;
}
